 \begin{align*} a^4 + a^{-4} &= (a^2 + a^{-2})^2 - 2 \\ &= [(a + a^{-1})^2 - 2]^2 - 2 \\ &= \boxed{\textbf{(D)}\ 194}. \end{align*} 
